import { OpenAIChat } from "../protocols/openai-chat.js";
import { Route } from "../route/client.js";
import { Endpoint } from "../route/endpoint.js";
import { ProviderID } from "../schema/index.js";
import { GoogleVertexShared } from "./google-vertex-shared.js";
export const id = ProviderID.make("google-vertex");
const route = Route.make({
    id: "google-vertex-chat",
    provider: id,
    providerMetadataKey: "vertex",
    protocol: OpenAIChat.protocol,
    endpoint: Endpoint.path("/chat/completions"),
    framing: OpenAIChat.framing,
});
export const routes = [route];
const configuredRoute = (input) => GoogleVertexShared.oauthRoute(route, "Chat", input, (project, location) => `https://aiplatform.googleapis.com/v1/projects/${project}/locations/${location}/endpoints/openapi`);
export const configure = (input = {}) => {
    const route = configuredRoute(input);
    return {
        id,
        model: (modelID) => route.model({ id: modelID }),
        configure,
    };
};
export const provider = {
    id,
    configure,
};
export const model = (modelID, settings = {}) => configure(GoogleVertexShared.oauthSettings("Chat", settings)).model(modelID);
